import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int totalLines = 2;
        String[] inputs = new String[totalLines];
        for (int i = 0; i < totalLines; i++) {
            inputs[i] = reader.readLine();
        }
        int n = Integer.parseInt(inputs[0]);
        String text = inputs[1] + "_";

        boolean inParentheses = false, inWord = false;
        int wordCount = 0, currentLength = 0, maxLength = 0;

        for (int i = 0; i <= n; i++) {
            char ch = text.charAt(i);
            if (inWord && (ch == '_' || ch == '(' || ch == ')')) {
                inWord = false;
                if (inParentheses) {
                    wordCount++;
                } else if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
                if (ch == '(') {
                    inParentheses = true;
                }
                if (ch == ')') {
                    inParentheses = false;
                }
                currentLength = 0;
            } else if (!inWord && !(ch == '_' || ch == '(' || ch == ')')) {
                inWord = true;
                currentLength++;
            } else if (inWord) {
                currentLength++;
            } else {
                if (ch == '(') {
                    inParentheses = true;
                } else if (ch == ')') {
                    inParentheses = false;
                }
            }
        }
        writer.printf("%d %d", maxLength, wordCount);
        writer.close();
    }
}
